// TH18 v1.00a st06bs.ecl.txt:761-829 (BossCard2) + 830-910 (BossCard2_at/BossCard2_at2).
// Source card 「弾幕狂蒐家の妄執」, spell id 64, source timeout 4200.
// Shell: control enemy at (0,0) owns the spell and the 120-frame prep buffer;
// the real boss starts at the common Boss entry (0,128) and keeps source hitboxes.
// Source t0 = first frame of boss_card2; TIME_LIMIT = 120 + 4200 + 2.
const TIME_LIMIT: int = 4322;
const HALF_TURN: int = 32768;
const TH18_SHARD: int = 512;    // source etSprite type 10, radius 2.4
const TH18_TALISMAN: int = 528; // source etSprite type 11, radius 2.8

// Source at() EX B:839-851: ANIM(a=1), OFFSCREEN(300,b=0), WAIT(60),
// VELTIME(120,r=1.0 or 1.5).  Two effect-end reruns make OFFSCREEN 298.
// ANIM retreat (-4*0.2 = -0.8) is kept as sh_dist(-0.8).
xformdef SHARD_KEEP(delta: fx) {
    offscreen_keep(298);
    @60 add_speed(0fx);      // explicit WAIT(60); birth animation omitted
    @120 set_accel(delta);   // VELTIME: (r-0.2)/120 per tick along heading
    stop_fx();
}

// Source at2() EX B:901-904: same chain with WAIT(60) and VELTIME(400,r=6.0).
// Only WAIT ends before the 300-frame OFFSCREEN window, so keep 299.
xformdef TALISMAN_KEEP(unused: int) {
    offscreen_keep(299);
    @60 add_speed(0fx);
    @400 set_accel(0.014fx); // (6.0-0.4)/400
    stop_fx();
}

// Source B:884-909 BossCard2_at2(0,2): mode3 fixed-direction ring, 20/50/55/70 ways,
// type 11 color 2, speed 0.4, random base angle RANDRAD, etDist -270.
sub emit_ring(count: int) {
    var alpha: angle = (rand(65536) - 32768) as angle; // RANDRAD
    sh_reset(0);
    sh_sprite(0, TH18_TALISMAN, 2);
    sh_aim(0, 0);
    sh_ring(0, 1);
    sh_count(0, count, 1);
    sh_angle(0, alpha, 0deg);
    sh_speed(0, 0.4fx, 0fx);
    sh_xform(0, TALISMAN_KEEP(0));
    sh_dist(0, -271.6fx); // etDist(-270) plus ANIM retreat -1.6
    sh_fire(0);
}

// Source B:830-883 BossCard2_at(A,B): one fixed-direction emitter, type 10,
// count 1, speed 0.2, EX WAIT 60 + VELTIME 120.  Each pass fires one shard at the
// player plus one mirrored across x=0 and y=FINAL_Y, with independent RANDF2
// draws in source order (angle, radial offset, angle, radial offset).
async sub at_stream(color: int, count: int, interval: int, delta: fx) {
    var aim: angle = 0deg;
    var a1: angle = 0deg;
    var a2: angle = 0deg;
    var ra1: angle = 0deg;
    var ra2: angle = 0deg;
    var x1: fx = 0fx;
    var y1: fx = 0fx;
    var x2: fx = 0fx;
    var y2: fx = 0fx;
    sh_reset(0);
    sh_sprite(0, TH18_SHARD, color);
    sh_aim(0, 0);
    sh_ring(0, 0);
    sh_count(0, 1, 1);
    sh_speed(0, 0.2fx, 0fx);
    sh_xform(0, SHARD_KEEP(delta));
    sh_dist(0, -0.8fx); // ANIM retreat -4*0.2
    loop {
        for i in 0..count {
            // B:858-861 first shard.
            aim = aim_player();
            a1 = ((aim as int) - HALF_TURN + (rand(65536) - 32768) / 4) as angle;
            ra1 = ((aim as int) + (rand(65536) - 32768) / 3) as angle;
            x1 = $player_x + 64fx * cos(ra1);
            y1 = $player_y + 64fx * sin(ra1);
            sh_angle(0, a1, 0deg);
            sh_offset_abs(0, x1, y1);
            sh_offset_rad(0, ra1, 64fx);
            sh_fire(0);
            // B:862-865 mirrored shard; radial angle also gets -pi.
            aim = aim_player();
            a2 = ((aim as int) - HALF_TURN + (rand(65536) - 32768) / 4) as angle;
            ra2 = ((aim as int) + (rand(65536) - 32768) / 3 - HALF_TURN) as angle;
            x2 = -$player_x + 64fx * cos(ra2);
            y2 = 448fx - $player_y + 64fx * sin(ra2);
            sh_angle(0, a2, 0deg);
            sh_offset_abs(0, x2, y2);
            sh_offset_rad(0, ra2, 64fx);
            sh_fire(0);
            // B:866-875: wait 20/6/5/4 by rank.
            wait(interval);
        }
        // B:878 source wait(720) between outer passes.
        wait(720);
    }
}

async sub boss_card2() {
    set_invuln(65535);
    set_hitbox(24fx);   // source B:34 48x48 body box
    set_hurtbox(20fx);  // source B:33 40x40 hurt box

    var rank: int = global(GVAR_RANK);
    var ring_n: int = 20;
    var d: int = 9;
    var interval: int = 20;
    var delta: fx = 0.0066667fx; // (1.0-0.2)/120
    if rank == 1 { ring_n = 50; d = 30; interval = 6; }
    if rank == 2 { ring_n = 55; d = 36; interval = 5; }
    if rank == 3 { ring_n = 70; d = 45; interval = 4; delta = 0.0108333fx; }

    // B:797-804: quad-out 190-frame move from the common Boss entry (0,128)
    // to (0,224); the first ring fires at source t=90 while still moving.
    move_to(190, 0fx, 224fx, EASE_QUAD_OUT);
    wait(90);
    emit_ring(ring_n);
    // B:804-805: first async stream starts at source t=290.
    wait(200);
    // B:813-821: the five async streams start 180 frames apart.
    spawn at_stream(4, d, interval, delta);
    wait(180);
    spawn at_stream(6, d, interval, delta);
    wait(180);
    spawn at_stream(10, d, interval, delta);
    wait(180);
    spawn at_stream(13, d, interval, delta);
    wait(180);
    spawn at_stream(2, d, interval, delta);
    // B:822-826: remaining source timeline is the 100-frame idle loop until
    // the 4200-frame timeout; successor Boss3 is the segment boundary.
    wait(3190);
    return;
}

async sub pattern() {
    wait(120); // prep buffer; attack starts on the next boss task frame
    _ = spawn_enemy(0fx, 128fx, 1000, 0, 0, 0, boss_card2);
    loop { wait(1); }
}

async sub control_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    spell_begin(0, 64, pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control_main);
    loop { wait(600); }
}
